        def dfs(node, color, colors):
            colors[node] = color
            for neighbor in adj_list[node]:
                if colors[neighbor] == -1:
                    if not dfs(neighbor, 1 - color, colors):
                        return False
                elif colors[neighbor] == color:
                    return False
            return True

        colors = [-1] * (n + 1)
        bipartite = True
        for i in range(1, n + 1):
            if colors[i] == -1:
                if not dfs(i, 0, colors):
                    bipartite = False
                    break

        if not bipartite:
